// Regenerates ../runtime-sql.ts and ../runtime-prelude.sql from the Rust
// reference sources, byte for byte. `test/runtime-sql.test.ts` fails when the
// generated file no longer matches them.
//
//   node kernel/migrate/verify/generate-runtime-sql.mjs   (from cloudflare/)
import { readFileSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";


export function extract(sources) {
  const provision = sources.provision;
  const identity = /const TENANT_IDENTITY_SQL: &str = r#"([\s\S]*?)"#;/.exec(provision)?.[1];
  const ledger = /CREATE TABLE IF NOT EXISTS gonvex_migrations \([\s\S]*?\{\}\),[\s\S]*?\n\s*\)/.exec(provision)?.[0];
  const nowMs = /pub const NOW_MS: &str = "([^"]+)";/.exec(sources.feed)?.[1];
  if (!identity || !ledger || !nowMs) throw new Error("Rust sources changed shape: TENANT_IDENTITY_SQL, gonvex_migrations DDL or NOW_MS not found");
  return {
    TENANT_IDENTITY_SQL: identity,
    REFERENCE_SCHEMA_SQL: sources.reference,
    SCHEMA_OPTIONS_SQL: sources.options,
    LEDGER_SQL: ledger.replace("{}", nowMs),
    NOW_MS: nowMs,
  };
}

export function render(values) {
  const lines = [
    "// Generated by kernel/migrate/verify/generate-runtime-sql.mjs from the Rust reference, byte for byte:",
    "// rust/crates/store/src/provision.rs (TENANT_IDENTITY_SQL, the gonvex_migrations DDL),",
    "// rust/crates/store/src/feed.rs (NOW_MS), reference_integrity/schema.sql and schema_options.sql.",
    "// Do not edit by hand; test/runtime-sql.test.ts checks it against those files.",
    "",
  ];
  for (const [name, value] of Object.entries(values)) lines.push(`export const ${name} = ${JSON.stringify(value)};`, "");
  return lines.join("\n");
}

/** The A01 drift job's prelude (0024 §1): the runtime DDL that precedes the app's migrations, in Rust's order. */
export const preludeSql = (values) => [values.TENANT_IDENTITY_SQL, values.REFERENCE_SCHEMA_SQL, values.SCHEMA_OPTIONS_SQL, values.LEDGER_SQL + ";\n"].join("\n");

if (typeof process !== "undefined" && process.argv?.[1] === fileURLToPath(import.meta.url)) {
  const here = dirname(fileURLToPath(import.meta.url));
  const store = join(here, "../../../../rust/crates/store/src");
  const read = (p) => readFileSync(join(store, p), "utf8");
  const values = extract({
    provision: read("provision.rs"),
    feed: read("feed.rs"),
    reference: read("reference_integrity/schema.sql"),
    options: read("schema_options.sql"),
  });
  writeFileSync(join(here, "../runtime-sql.ts"), render(values));
  writeFileSync(join(here, "../runtime-prelude.sql"), preludeSql(values));
  console.log("wrote runtime-sql.ts and runtime-prelude.sql");
}
